27	// Discover returns Claude transcript files for the repo modified within the
28	// lookback window. overridePath replaces the default ~/.claude/projects/<slug>
29	// dir; sessionFilter, when non-empty, keeps only matching session IDs (the
30	// file stem).
31	func (claudeImporter) Discover(repoRoot, overridePath string, now time.Time, sessionFilter []string) ([]SessionFile, error) {
32		dir := overridePath
33		if dir == "" {
34			ag := &claudecode.ClaudeCodeAgent{}
35			d, err := ag.GetSessionDir(repoRoot)
36			if err != nil {
37				return nil, fmt.Errorf("resolve claude session dir: %w", err)
38			}
39			dir = d
40		}
41		entries, err := os.ReadDir(dir)
42		if err != nil {
43			if os.IsNotExist(err) {
44				return nil, nil // no transcripts for this repo
45			}
46			return nil, fmt.Errorf("read claude session dir: %w", err)
47		}
48		cutoff := now.AddDate(0, 0, -LookbackDays)
49		var out []SessionFile
50		for _, e := range entries {
51			if e.IsDir() || !strings.HasSuffix(e.Name(), ".jsonl") {
52				continue
53			}
54			stem := strings.TrimSuffix(e.Name(), ".jsonl")
55			if len(sessionFilter) > 0 && !slices.Contains(sessionFilter, stem) {
56				continue
57			}
58			info, err := e.Info()
59			if err != nil {
60				continue
61			}
62			if info.ModTime().Before(cutoff) {
63				continue
64			}
65			out = append(out, SessionFile{Path: filepath.Join(dir, e.Name()), SessionID: stem})
66		}
67		slices.SortFunc(out, func(a, b SessionFile) int { return strings.Compare(a.Path, b.Path) })
68		return out, nil
69	}
