71	// SplitTurns produces one Turn per user-prompt line. Token usage for each turn
72	// is computed on the slice [LineStart, LineEnd) so turns don't double-count
73	// later turns. tool_result lines (Type == "user" but no text content) do not
74	// start a turn.
75	func (claudeImporter) SplitTurns(sf SessionFile, full []byte) ([]Turn, error) {
76		subagentsDir := filepath.Join(filepath.Dir(sf.Path), sf.SessionID, "subagents")
77		rawLines := splitRawLines(full)
78	
79		// Identify user-prompt turn starts in raw-line space.
80		var starts []int
81		for i, raw := range rawLines {
82			if isUserPromptLine(raw) {
83				starts = append(starts, i)
84			}
85		}
86	
87		ag := &claudecode.ClaudeCodeAgent{}
88		turns := make([]Turn, 0, len(starts))
89		for k, start := range starts {
90			end := len(rawLines)
91			if k+1 < len(starts) {
92				end = starts[k+1]
93			}
94	
95			// Bound token usage to [start, end): truncate to the first `end` lines,
96			// then let the agent helper slice from `start`.
97			truncated := joinLines(rawLines[:end])
98			tokens, err := ag.CalculateTotalTokenUsage(truncated, start, subagentsDir)
99			if err != nil {
100				return nil, fmt.Errorf("token usage for turn %d: %w", k, err)
101			}
102	
103			var rec struct {
104				UUID       string          `json:"uuid"`
105				Message    json.RawMessage `json:"message"`
106				ParentUUID string          `json:"parentUuid"`
107				Timestamp  string          `json:"timestamp"`
108			}
109			if err := json.Unmarshal(rawLines[start], &rec); err != nil {
110				// Already validated as a user-prompt line in isUserPromptLine; skip
111				// defensively if it somehow fails to parse here.
112				continue
113			}
114			ts, parseErr := time.Parse(time.RFC3339, rec.Timestamp)
115			if parseErr != nil {
116				ts = time.Time{}
117			}
118	
119			slice := joinLines(rawLines[start:end])
120			sum := sha256.Sum256(slice)
121	
122			turns = append(turns, Turn{
123				LineStart:   start,
124				LineEnd:     end,
125				UUID:        rec.UUID,
126				ParentUUID:  rec.ParentUUID,
127				Prompt:      transcript.ExtractUserContent(rec.Message),
128				Model:       modelInRange(rawLines, start, end),
129				CreatedAt:   ts,
130				Tokens:      tokens,
131				ContentHash: "sha256:" + hex.EncodeToString(sum[:]),
132			})
133		}
134		return turns, nil
135	}
