146	// modelInRange returns the model from the first assistant message within
147	// [start, end), or "" when none carries one. The model lives on assistant
148	// lines, not the user-prompt line.
149	func modelInRange(rawLines [][]byte, start, end int) string {
150		for i := start; i < end && i < len(rawLines); i++ {
151			var line transcript.Line
152			if err := json.Unmarshal(rawLines[i], &line); err != nil {
153				continue
154			}
155			if line.Type != "assistant" {
156				continue
157			}
158			var ex claudeExtraFields
159			if err := json.Unmarshal(rawLines[i], &ex); err != nil {
160				continue
161			}
162			if ex.Message.Model != "" {
163				return ex.Message.Model
164			}
165		}
166		return ""
167	}
