169	// isUserPromptLine reports whether a raw JSONL line is a genuine user-prompt
170	// turn start: type "user" (or role "user") with non-empty extractable text.
171	// tool_result lines are type "user" but carry no text, so they return false.
172	func isUserPromptLine(raw []byte) bool {
173		var line transcript.Line
174		if err := json.Unmarshal(raw, &line); err != nil {
175			return false
176		}
177		typ := line.Type
178		if typ == "" {
179			typ = line.Role
180		}
181		if typ != "user" {
182			return false
183		}
184		return transcript.ExtractUserContent(line.Message) != ""
185	}
