187	// splitRawLines splits content into raw lines in the same index space as
188	// transcript.SliceFromLine (newline-counted). Trailing empty segment from a
189	// final newline is dropped.
190	func splitRawLines(content []byte) [][]byte {
191		if len(content) == 0 {
192			return nil
193		}
194		parts := strings.Split(string(content), "\n")
195		if len(parts) > 0 && parts[len(parts)-1] == "" {
196			parts = parts[:len(parts)-1]
197		}
198		out := make([][]byte, len(parts))
199		for i, p := range parts {
200			out[i] = []byte(p)
201		}
202		return out
203	}
204	
205	// joinLines reassembles raw lines into newline-terminated bytes.
206	func joinLines(lines [][]byte) []byte {
207		if len(lines) == 0 {
208			return nil
209		}
210		strs := make([]string, len(lines))
211		for i, l := range lines {
212			strs[i] = string(l)
213		}
214		return []byte(strings.Join(strs, "\n") + "\n")
215	}
